        except Exception:
            pass
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        dx = 0 if bx == ax else (1 if bx > ax else -1)
        dy = 0 if by == ay else (1 if by > ay else -1)
        return [dx, dy]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        dx = 0 if bx == ax else (-1 if bx > ax else 1)
        dy = 0 if by == ay else (-1 if by > ay else 1)
        return [dx, dy]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = sg("environment_name", "resource_collection")
    s = pos(sg("self_position", (0, 0)))
